-- BACK-524: nullable private photo references, using the existing global storage provider.
-- No bytes, physical URLs, historical backfill or automatic CUSTOM grants.
SET @back524_ddl = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE dependents_dependent ADD COLUMN photo_storage_key VARCHAR(512) NULL', 'SELECT 1') FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'dependents_dependent' AND column_name = 'photo_storage_key');
PREPARE back524_statement FROM @back524_ddl;
EXECUTE back524_statement;
DEALLOCATE PREPARE back524_statement;
SET @back524_ddl = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE dependents_dependent_history ADD COLUMN photo_storage_key VARCHAR(512) NULL', 'SELECT 1') FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'dependents_dependent_history' AND column_name = 'photo_storage_key');
PREPARE back524_statement FROM @back524_ddl;
EXECUTE back524_statement;
DEALLOCATE PREPARE back524_statement;

